/**
 * Human-readable rendering of the common condition shapes.
 *
 * Conditions are authored as namespaced expressions
 * (`session.card_replace.replacement_reason == 'damaged'`); the simple,
 * frequent shapes read better as "If replacement_reason is damaged". Anything
 * beyond one comparison/negation falls back to the raw expression.
 */

export interface ConditionPhrase {
  /** Full namespaced path ("session.card_replace.replacement_reason"). */
  path: string;
  /** Bare memory entry name (namespace stripped). */
  entry: string;
  verb: "is" | "is not";
  /** Display value; quotes stripped, python literals lowered. */
  value: string;
}

const MEMORY_PATH = String.raw`(session\.[\w-]+\.([\w-]+))`;

const EQUALITY = new RegExp(`^${MEMORY_PATH}\\s*(==|!=)\\s*(.+)$`);
const NEGATION = new RegExp(`^not\\s+${MEMORY_PATH}$`);
const TRUTHY = new RegExp(`^${MEMORY_PATH}$`);

function displayValue(raw: string): string | null {
  const trimmed = raw.trim();
  const quoted = /^'([^']*)'$|^"([^"]*)"$/.exec(trimmed);
  if (quoted) return quoted[1] ?? quoted[2] ?? "";
  if (/^(True|False|None|-?\d+(\.\d+)?)$/.test(trimmed)) {
    return trimmed === "None" ? "empty" : trimmed.toLowerCase();
  }
  // A composite right-hand side (another memory path, arithmetic, ...) is not
  // worth phrasing — the raw expression is clearer.
  return null;
}

export function describeCondition(condition: string): ConditionPhrase | null {
  const trimmed = condition.trim();

  const equality = EQUALITY.exec(trimmed);
  if (equality) {
    const value = displayValue(equality[4]);
    if (value === null) return null;
    return {
      path: equality[1],
      entry: equality[2],
      verb: equality[3] === "==" ? "is" : "is not",
      value,
    };
  }

  const negation = NEGATION.exec(trimmed);
  if (negation) {
    return { path: negation[1], entry: negation[2], verb: "is not", value: "set" };
  }

  const truthy = TRUTHY.exec(trimmed);
  if (truthy) {
    return { path: truthy[1], entry: truthy[2], verb: "is", value: "set" };
  }

  return null;
}

/**
 * Parses a grammar right-hand side to the value it compares against: quoted
 * string, boolean, null, or number. Returns `{ value }` on success, `null` when
 * the literal is outside the grammar (a composite RHS, another memory path).
 */
function parseLiteral(raw: string): { value: unknown } | null {
  const trimmed = raw.trim();
  const quoted = /^'([^']*)'$|^"([^"]*)"$/.exec(trimmed);
  if (quoted) return { value: quoted[1] ?? quoted[2] ?? "" };
  if (trimmed === "True") return { value: true };
  if (trimmed === "False") return { value: false };
  if (trimmed === "None") return { value: null };
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) return { value: Number(trimmed) };
  return null;
}

function isSet(value: unknown): boolean {
  return value !== null && value !== undefined;
}

/**
 * Evaluates a condition against reconstructed memory, for historical mode where
 * no live evaluated_conditions exist. Intentionally covers ONLY the four phrase
 * shapes `describeCondition` parses (equals / not-equals / is-set / is-not-set)
 * and MUST stay in lockstep with it: anything unparseable or beyond that grammar
 * returns `undefined` (rendered as the neutral "unknown" state), never a guess.
 */
export function evaluateCondition(
  condition: string,
  memory: Record<string, { value: unknown }> | null | undefined,
): boolean | undefined {
  if (!memory) return undefined;
  const trimmed = condition.trim();

  const equality = EQUALITY.exec(trimmed);
  if (equality) {
    const literal = parseLiteral(equality[4]);
    if (literal === null) return undefined;
    const actual = memory[memoryKeyForPath(equality[1])]?.value ?? null;
    const equal = actual === literal.value;
    return equality[3] === "==" ? equal : !equal;
  }

  const negation = NEGATION.exec(trimmed);
  if (negation) {
    return !isSet(memory[memoryKeyForPath(negation[1])]?.value);
  }

  const truthy = TRUTHY.exec(trimmed);
  if (truthy) {
    return isSet(memory[memoryKeyForPath(truthy[1])]?.value);
  }

  return undefined;
}

const MEMORY_PATH_OCCURRENCES = /session\.[\w-]+\.[\w-]+/g;

/** Unique `session.*` paths referenced in *expression*, in source order. */
export function sessionPathsIn(expression: string): string[] {
  return [...new Set(expression.match(MEMORY_PATH_OCCURRENCES) ?? [])];
}

/** Memory-state key for a condition path (the `session.` prefix stripped). */
export function memoryKeyForPath(path: string): string {
  return path.replace(/^session\./, "");
}

const MAX_TOOLTIP_VALUE_LENGTH = 80;

function formatMemoryValue(value: unknown): string {
  if (value === null || value === undefined) return "not set";
  const text = typeof value === "string" ? value : JSON.stringify(value);
  return text.length > MAX_TOOLTIP_VALUE_LENGTH
    ? `${text.slice(0, MAX_TOOLTIP_VALUE_LENGTH - 1)}…`
    : text;
}

/**
 * One "entry = current value" line per memory path in *condition*, for the
 * hover tooltip on condition tags. Null when the condition references no
 * memory path or no memory state is available.
 */
export function conditionMemorySummary(
  condition: string,
  memory: Record<string, { value: unknown }> | null | undefined,
): string | null {
  if (!memory) return null;
  const paths = sessionPathsIn(condition);
  if (paths.length === 0) return null;
  // The tag already names the entry; the tooltip shows only the value(s).
  return paths.map((path) => formatMemoryValue(memory[memoryKeyForPath(path)]?.value)).join("\n");
}
